import { useState, useMemo } from "react";
import { Shuffle, Sparkles, Sun, Moon, EyeOff, RotateCcw } from "lucide-react";

// ---------------------------------------------------------------------------
// LOGO IMAGES — your actual uploaded logo artwork (reel + crank version),
// background removed and cropped tight. Embedded as data URIs so the file
// stays fully self-contained with no external image hosting needed.
// ---------------------------------------------------------------------------

const LOGO_LIGHT = "data:image/png;base64,";
const LOGO_DARK = "data:image/png;base64,";

// ---------------------------------------------------------------------------
// THEME
// Two full palettes, matching the two logo versions exactly. Only the
// accent color (coral) stays identical across both -- everything else flips.
// ---------------------------------------------------------------------------

const THEMES = {
  dark: {
    bg: "#151A24",
    surface: "#1F2534",
    border: "#2C3244",
    text: "#F2EFE6",
    muted: "#9BA0B5",
    accent: "#FF6B4A",
    logo: LOGO_DARK,
  },
  light: {
    bg: "#F5F3EE",
    surface: "#FFFFFF",
    border: "#DDD8CC",
    text: "#151A24",
    muted: "#6B6F80",
    accent: "#FF6B4A",
    logo: LOGO_LIGHT,
  },
};

// ---------------------------------------------------------------------------
// DATA -- curated mood-tagged movie catalog.
// ---------------------------------------------------------------------------

